<template>
  <AppPage eyebrow="SUPPLY · NOTIFICATIONS" title="供应商订单通知" subtitle="管理通知通道与订单通知记录。下单后由后台自动处理，页面不会手动发送消息。" :boundary-note="deliveryNote" :capability="capability" class="sc2-ui">
    <el-tabs v-model="activeTab" @tab-change="tabChanged">
      <el-tab-pane label="通道配置" name="channels">
        <div class="topline"><p>凭据仅写入、不读取。在线检查不会发消息；通道启用需完成至少两天、每天 6 条的真实验收。</p><el-button v-if="canNotify" type="primary" @click="newChannel">新增通道</el-button></div>
        <p v-if="auth.authorizationStale" class="error">权限信息过期，所有写操作已禁用。</p>
        <el-skeleton v-if="loadingChannels && !channels.length" :rows="4" animated />
        <div v-else class="table-wrap"><el-table :data="channels" border stripe row-key="id" min-width="1050">
          <el-table-column prop="name" label="通道" min-width="150"/><el-table-column prop="sender_name" label="发送账号" min-width="140"/><el-table-column prop="device_name" label="设备" min-width="120"/>
          <el-table-column label="状态" min-width="240"><template #default="{row}"><div class="tags"><el-tag :type="row.credential_configured?'success':'warning'">{{row.credential_configured?'凭据已配置':'缺少凭据'}}</el-tag><el-tag :type="row.connectivity==='online'?'success':row.connectivity==='offline'?'danger':'info'">{{connectionLabel(row.connectivity)}}</el-tag><el-tag :type="row.qualified?'success':'warning'">{{row.qualified?'验收已登记':'未验收'}}</el-tag><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'通道已启用':'通道停用'}}</el-tag></div><small>最后检查：{{date(row.last_checked_at)}}</small></template></el-table-column>
          <el-table-column label="受控操作" min-width="390" fixed="right"><template #default="{row}"><div class="actions"><el-button size="small" @click="editChannel(row)">配置</el-button><el-button size="small" :disabled="!canNotify || busyId===row.id" :loading="busyId===row.id && busyAction==='check'" @click="runChannel(row,'check')">只读在线检查</el-button><el-button size="small" :disabled="!canNotify" @click="openQualification(row)">登记验收</el-button><el-button size="small" :disabled="!canNotify" @click="showCallback(row)">回调配置</el-button></div></template></el-table-column>
        </el-table></div>
        <p v-if="channelError" class="error">{{channelError}}</p>
        <el-dialog v-model="channelDialog" :title="editing?.id ? '编辑通知通道' : '新增通知通道'" width="min(650px, 95vw)" @closed="clearCredential" class="sc2-ui">
          <el-form label-position="top" class="form-grid"><el-form-item label="通道名称"><el-input v-model="channelForm.name" :disabled="busy || !canNotify" maxlength="100"/></el-form-item><el-form-item label="发送账号"><el-input v-model="channelForm.sender_name" :disabled="busy || !canNotify" maxlength="100"/></el-form-item><el-form-item label="设备名称"><el-input v-model="channelForm.device_name" :disabled="busy || !canNotify" maxlength="100"/></el-form-item>
            <el-form-item label="机器人凭据（仅写入，不会回显）"><el-input v-model="credential.robot_id" type="password" show-password autocomplete="new-password" :disabled="busy || !canNotify" placeholder="仅在需要设置或轮换凭据时填写"/><el-input v-model="credential.reason" class="reason-input" :disabled="busy || !canNotify" maxlength="300" placeholder="凭据设置/轮换原因"/></el-form-item>
            <el-form-item v-if="editing?.id" label="通道启用"><el-switch v-model="channelForm.enabled" :disabled="busy || !canNotify || (!editing.qualified && !editing.enabled)"/><small>启用须完成验收；生产发送独立开关仍保持关闭。</small></el-form-item>
          </el-form>
          <template #footer><el-button @click="channelDialog=false">取消</el-button><el-button type="primary" :disabled="busy || !canNotify || !channelValid" :loading="busy" @click="saveChannel">保存配置</el-button></template>
        </el-dialog>
        <el-dialog v-model="qualificationDialog" title="登记真实通道验收" width="min(680px, 95vw)" class="sc2-ui">
          <el-alert type="warning" :closable="false" title="登记验收要求：两天每天至少 6 条。当前设备账号未备妥时，请勿虚构验收证据。"/>
          <el-form label-position="top" class="form-grid qualify-form"><el-form-item label="第一天"><el-date-picker v-model="qualification.first_day" type="date" value-format="YYYY-MM-DD" :disabled="busy || !canNotify"/><el-input-number v-model="qualification.first_day_count" :min="0" :max="10000" :disabled="busy || !canNotify"/></el-form-item><el-form-item label="第二天"><el-date-picker v-model="qualification.second_day" type="date" value-format="YYYY-MM-DD" :disabled="busy || !canNotify"/><el-input-number v-model="qualification.second_day_count" :min="0" :max="10000" :disabled="busy || !canNotify"/></el-form-item><el-form-item label="验收证据" class="full"><el-input v-model="qualification.evidence" type="textarea" :rows="3" maxlength="2000" :disabled="busy || !canNotify" placeholder="记录真实执行、群内结果及核验时间"/></el-form-item><div class="checks full"><el-checkbox v-model="qualification.contains_external_member" :disabled="busy || !canNotify">群内包含供应商外部成员</el-checkbox><el-checkbox v-model="qualification.documents_opened" :disabled="busy || !canNotify">已打开并核对订单文件</el-checkbox><el-checkbox v-model="qualification.supplier_saved" :disabled="busy || !canNotify">供应商已填写并保存发货内容</el-checkbox><el-checkbox v-model="qualification.automatic_without_confirmation" :disabled="busy || !canNotify">后台自动处理无需人工确认</el-checkbox></div></el-form>
          <template #footer><el-button @click="qualificationDialog=false">取消</el-button><el-button type="primary" :disabled="busy || !canNotify || !qualificationValid" :loading="busy" @click="saveQualification">登记验收</el-button></template>
        </el-dialog>
        <el-dialog v-model="callbackDialog" title="工具回调配置" width="min(650px, 95vw)" class="sc2-ui"><p>此链接用于在配置工具中登记执行结果回调，不是供应商链接。请按内部凭据规范保存。</p><el-input :model-value="callbackUrl" readonly/><template #footer><el-button @click="copyCallback">复制</el-button><el-button @click="callbackDialog=false">关闭</el-button></template></el-dialog>
      </el-tab-pane>

      <el-tab-pane label="订单通知记录" name="records">
        <div class="filters"><el-input v-model="search" clearable placeholder="订单号 / 供应商" aria-label="通知记录搜索" @keyup.enter="loadRecords"/><el-select v-model="statusFilter" clearable placeholder="全部状态" aria-label="通知状态"><el-option v-for="s in statuses" :key="s.value" :label="s.label" :value="s.value"/></el-select><el-button type="primary" plain :loading="loadingRecords" @click="loadRecords">查询</el-button></div>
        <p>记录仅用于观察后台自动处理、核对结果或登记证据。接口受理、工具执行成功都不代表群内送达。</p>
        <div class="table-wrap"><el-table :data="records" border stripe row-key="id" min-width="920"><el-table-column prop="order_number" label="采购订单" min-width="170"/><el-table-column prop="supplier_name" label="供应商" min-width="150"/><el-table-column label="通知状态" min-width="170"><template #default="{row}"><el-tag :type="tagType(row.status)">{{statusLabel(row.status)}}</el-tag><div v-if="row.blocked_message" class="small">{{row.blocked_message}}</div></template></el-table-column><el-table-column prop="summary" label="通知摘要" min-width="260" show-overflow-tooltip/><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><el-button size="small" @click="openRecord(row)">查看详情</el-button></template></el-table-column></el-table></div>
        <div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @change="loadRecords"/></div>
        <el-drawer v-model="detailOpen" title="订单通知详情" size="min(760px, 96vw)" class="sc2-ui"><OrderNotificationV2 v-if="selectedOrderId" :key="selectedOrderId" :order-id="selectedOrderId"/></el-drawer>
      </el-tab-pane>
    </el-tabs>
  </AppPage>
</template>

<script setup>
import '../../styles/supplyTypography.css';
import { computed, onMounted, reactive, ref } from 'vue';
import { useAuthStore } from '../../stores/auth';
import OrderNotificationV2 from '../../components/supply-chain/OrderNotificationV2.vue';
import { checkNotificationChannel, createNotificationChannel, fetchNotificationCallbackLink, fetchNotificationChannels, fetchSupplyNotifications, qualifyNotificationChannel, setNotificationChannelCredentials, updateNotificationChannel } from '../../api/supplyNotificationsV2';

const auth=useAuthStore();const canManage=computed(()=>auth.hasPermission('supply.v2.manage')&&!auth.authorizationStale);const canNotify=computed(()=>canManage.value&&auth.hasPermission('supply.v2.notify'));
const capability=computed(()=>canNotify.value?'connected':'disabled');
const deliveryNote=computed(()=>{
  const value=channels.value[0]?.live_delivery_enabled;
  const state=loadingChannels.value?'读取中':channelError.value?'读取失败，请重试':typeof value==='boolean'?(value?'已开启':'未开启'):'无法确认（当前无可用通道或开关信息）';
  return `对外投递开关：${state}。通道验收、启用状态分别见下表；保存配置不会开启系统发送开关。`;
});
const activeTab=ref('channels');const channels=ref([]);const records=ref([]);const loadingChannels=ref(false);const loadingRecords=ref(false);const channelError=ref('');const busy=ref(false);const busyId=ref(null);const busyAction=ref('');
const channelDialog=ref(false);const editing=ref(null);const credential=reactive({robot_id:'',reason:''});const channelForm=reactive({name:'',sender_name:'',device_name:'',enabled:false});
const qualificationDialog=ref(false);const qualifying=ref(null);const qualification=reactive({first_day:'',second_day:'',first_day_count:6,second_day_count:6,evidence:'',contains_external_member:false,documents_opened:false,supplier_saved:false,automatic_without_confirmation:false});
const callbackDialog=ref(false);const callbackUrl=ref('');const search=ref('');const statusFilter=ref('');const page=ref(1);const pageSize=ref(20);const total=ref(0);const detailOpen=ref(false);const selectedOrderId=ref(null);
const channelValid=computed(()=>channelForm.name.trim()&&channelForm.sender_name.trim()&&channelForm.device_name.trim()&&(!channelForm.enabled||editing.value?.qualified));
const qualificationValid=computed(()=>qualification.first_day&&qualification.second_day&&qualification.first_day<qualification.second_day&&qualification.first_day_count>=6&&qualification.second_day_count>=6&&qualification.evidence.trim()&&qualification.contains_external_member&&qualification.documents_opened&&qualification.supplier_saved&&qualification.automatic_without_confirmation);
const statuses=[{value:'blocked',label:'待配置/需处理'},{value:'queued',label:'待发送'},{value:'sending',label:'发送中'},{value:'awaiting_execution',label:'接口已受理'},{value:'awaiting_verification',label:'工具已执行待核实'},{value:'delivered',label:'群内已核实'},{value:'failed',label:'失败'},{value:'unknown',label:'结果未知'},{value:'offline',label:'发送端离线'}];
function statusLabel(s){return statuses.find(x=>x.value===s)?.label||s||'—'}function tagType(s){return s==='delivered'?'success':['failed','unknown','offline','blocked'].includes(s)?'danger':['queued','sending','awaiting_execution','awaiting_verification'].includes(s)?'warning':'info'}function connectionLabel(s){return ({online:'在线',offline:'离线',unknown:'未检查'})[s]||'未检查'}function date(v){return v?new Date(v).toLocaleString('zh-CN'):'未检查'}
async function loadChannels(){loadingChannels.value=true;channelError.value='';try{const r=await fetchNotificationChannels();if(!r?.success)throw new Error(r?.message||'读取通道失败');channels.value=r.data||[]}catch(e){channelError.value=e?.message||'读取通道失败'}finally{loadingChannels.value=false}}
async function loadRecords(){loadingRecords.value=true;try{const r=await fetchSupplyNotifications({search:search.value,status:statusFilter.value,limit:pageSize.value,offset:(page.value-1)*pageSize.value});if(!r?.success)throw new Error(r?.message||'读取通知记录失败');records.value=Array.isArray(r.data)?r.data:(r.data?.results||r.data?.items||[]);total.value=r.count??r.data?.count??records.value.length}catch(e){channelError.value=e?.message||'读取通知记录失败'}finally{loadingRecords.value=false}}
function tabChanged(tab){if(tab==='records')loadRecords();else loadChannels()}
function newChannel(){editing.value=null;Object.assign(channelForm,{name:'',sender_name:'',device_name:'',enabled:false});clearCredential();channelDialog.value=true}
function editChannel(row){editing.value={...row};Object.assign(channelForm,{name:row.name,sender_name:row.sender_name,device_name:row.device_name,enabled:!!row.enabled});clearCredential();channelDialog.value=true}
function clearCredential(){credential.robot_id='';credential.reason=''}
async function saveChannel(){if(!canNotify.value||busy.value||!channelValid.value)return;busy.value=true;channelError.value='';try{let r;if(editing.value){r=await updateNotificationChannel(editing.value.id,{expected_version:editing.value.version,name:channelForm.name.trim(),sender_name:channelForm.sender_name.trim(),device_name:channelForm.device_name.trim(),enabled:channelForm.enabled})}else{r=await createNotificationChannel({name:channelForm.name.trim(),sender_name:channelForm.sender_name.trim(),device_name:channelForm.device_name.trim()})}if(!r?.success)throw new Error(r?.message||'保存通道失败');const saved=r.data;if(credential.robot_id.trim()){if(!credential.reason.trim())throw new Error('设置凭据时必须填写原因');const c=await setNotificationChannelCredentials(saved?.id||editing.value?.id,{expected_version:saved?.version??editing.value?.version,robot_id:credential.robot_id,reason:credential.reason.trim()});if(!c?.success)throw new Error(c?.message||'通道已保存，但凭据写入失败')}clearCredential();channelDialog.value=false;await loadChannels()}catch(e){channelError.value=e?.message||'保存失败；若网络结果未知，请刷新核对状态'}finally{busy.value=false}}
async function runChannel(row,action){if(!canNotify.value||busy.value)return;busy.value=true;busyId.value=row.id;busyAction.value=action;try{const r=await checkNotificationChannel(row.id,{expected_version:row.version});if(!r?.success)throw new Error(r?.message||'在线检查失败');await loadChannels()}catch(e){channelError.value=e?.message||'检查失败；未发送消息'}finally{busy.value=false;busyId.value=null;busyAction.value=''}}
function openQualification(row){qualifying.value=row;Object.assign(qualification,{first_day:'',second_day:'',first_day_count:6,second_day_count:6,evidence:'',contains_external_member:false,documents_opened:false,supplier_saved:false,automatic_without_confirmation:false});qualificationDialog.value=true}
async function saveQualification(){if(!canNotify.value||busy.value||!qualificationValid.value)return;busy.value=true;try{const r=await qualifyNotificationChannel(qualifying.value.id,{expected_version:qualifying.value.version,...qualification});if(!r?.success)throw new Error(r?.message||'验收登记失败');qualificationDialog.value=false;await loadChannels()}catch(e){channelError.value=e?.message||'验收登记失败'}finally{busy.value=false}}
async function showCallback(row){try{const r=await fetchNotificationCallbackLink(row.id);if(!r?.success)throw new Error(r?.message||'读取回调配置失败');callbackUrl.value=r.data?.url||'';callbackDialog.value=true}catch(e){channelError.value=e?.message||'读取回调配置失败'}}
async function copyCallback(){try{await navigator.clipboard.writeText(callbackUrl.value)}catch{channelError.value='无法访问剪贴板，请手动复制回调地址'}}
function openRecord(row){selectedOrderId.value=row.order_id;detailOpen.value=true}
onMounted(loadChannels);
</script>

<style scoped>
.topline,.filters{display:flex;align-items:center;gap:12px;justify-content:space-between;margin:12px 0}.topline p{color:#657184}.filters{justify-content:flex-start}.filters .el-input{max-width:340px}.filters .el-select{width:200px}.table-wrap{width:100%;overflow-x:auto;margin-top:14px}.tags,.actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.small,small{display:block;color:#657184;margin-top:5px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.form-grid :deep(.el-date-editor){width:100%}.reason-input{margin-top:8px}.qualify-form .el-form-item{display:block}.full{grid-column:1/-1}.checks{display:flex;gap:12px;flex-wrap:wrap}.error{color:#c0392b}.pagination{display:flex;justify-content:flex-end;margin-top:14px}@media(max-width:600px){.topline,.filters{align-items:stretch;flex-direction:column}.filters .el-input,.filters .el-select{max-width:none;width:100%}.form-grid{grid-template-columns:minmax(0,1fr)}.checks{display:grid;grid-template-columns:1fr}.pagination{overflow-x:auto;justify-content:flex-start}}
</style>
